// Independent vector-form reader: no model.rs or semantic.rs import.
// Boolean/involution shortcuts are checked inapplicable on these two programs.
use zopro_bn254::Fr;use serde_json::{json,Value};use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/semantic-cse176";
type Lc=Vec<(usize,Fr)>;type Key=([u64;4],Vec<(usize,[u64;4])>);type OpKey=(u8,usize,Vec<Key>);
fn norm(mut a:Lc)->Lc{a.sort_unstable_by_key(|v|v.0);let mut out:Lc=vec![];for(i,c)in a{if let Some(last)=out.last_mut().filter(|v|v.0==i){last.1+=c;}else{out.push((i,c));}}out.retain(|v|v.1!=Fr::ZERO);out}
fn add(mut a:Lc,b:Lc)->Lc{a.extend(b);norm(a)}fn scale(a:&Lc,c:Fr)->Lc{norm(a.iter().map(|&(i,x)|(i,x*c)).collect())}fn sub(a:Lc,b:&Lc)->Lc{add(a,scale(b,-Fr::ONE))}
fn constant(a:&Lc)->Option<Fr>{if a.iter().any(|v|v.0!=0){None}else{Some(a.first().map_or(Fr::ZERO,|v|v.1))}}
fn key(a:&Lc)->Key{(a.iter().find(|v|v.0==0).map_or(Fr::ZERO,|v|v.1).to_canonical(),a.iter().filter(|v|v.0!=0).map(|(i,c)|(*i,c.to_canonical())).collect())}
fn monic(a:&Lc)->(Fr,Lc){let c=a.iter().find(|v|v.0!=0).or_else(||a.first()).map_or(Fr::ZERO,|v|v.1);if c==Fr::ZERO{(c,vec![])}else{(c,scale(a,c.inverse().unwrap()))}}
struct Cursor<'a>{b:&'a[u8],at:usize}impl Cursor<'_>{fn word(&mut self)->usize{let w=u32::from_le_bytes(self.b[self.at..self.at+4].try_into().unwrap());self.at+=4;w as usize}fn field(&mut self)->Fr{let w=std::array::from_fn(|_|{let lo=self.word()as u64;let hi=self.word()as u64;lo|(hi<<32)});assert!(w.iter().rev().cmp(Fr::MODULUS.iter().rev()).is_lt());Fr::from_montgomery(w)}}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
struct Cse{next:usize,seen:BTreeMap<OpKey,usize>,bits:BTreeSet<usize>,inv:BTreeSet<usize>,requests:[usize;4],hits:[usize;4],wire_exact:BTreeSet<Key>,wire_monic:BTreeSet<Key>,wire_hits:[usize;2]}
impl Cse{
fn new(nw:usize)->Self{Self{next:nw,seen:BTreeMap::new(),bits:BTreeSet::new(),inv:BTreeSet::new(),requests:[0;4],hits:[0;4],wire_exact:BTreeSet::new(),wire_monic:BTreeSet::new(),wire_hits:[0;2]}}
fn bool_shape(&self,a:&Lc)->Option<(usize,bool)>{let mut non=a.iter().filter(|v|v.0!=0);let&(i,c)=non.next()?;if non.next().is_some()||c!=Fr::ONE||!self.bits.contains(&i){return None;}let c=a.iter().find(|v|v.0==0).map_or(Fr::ZERO,|v|v.1);if c==Fr::ZERO{Some((i,false))}else if c== -Fr::ONE{Some((i,true))}else{None}}
fn atom(&mut self,kind:u8,index:usize,args:Vec<Key>)->Lc{let k=(kind,index,args);let id=if let Some(&id)=self.seen.get(&k){self.hits[kind as usize]+=1;id}else{let id=self.next;self.next+=1;self.seen.insert(k,id);id};if kind==1{self.inv.insert(id);}if kind==2{self.bits.insert(id);}vec![(id,Fr::ONE)]}
fn note(&mut self,a:&Lc){self.wire_hits[0]+=usize::from(!self.wire_exact.insert(key(a)));let(c,m)=monic(a);if c!=Fr::ZERO{self.wire_hits[1]+=usize::from(!self.wire_monic.insert(key(&m)));}}
fn product(&mut self,a:&Lc,b:&Lc)->Lc{self.requests[0]+=1;let(ca,a)=monic(a);let(cb,b)=monic(b);assert!(constant(&a).is_none()&&constant(&b).is_none());if let(Some((i,_)),Some((j,_)))=(self.bool_shape(&a),self.bool_shape(&b)){assert_ne!(i,j,"Boolean shortcut would require this verifier to be extended");}let mut keys=vec![key(&a),key(&b)];keys.sort();let atom=self.atom(0,0,keys);scale(&atom,ca*cb)}
fn inverse(&mut self,a:&Lc)->Lc{self.requests[1]+=1;if let Some(c)=constant(a){return norm(vec![(0,c.inverse().unwrap_or(Fr::ZERO))]);}let(c,m)=monic(a);assert!(self.bool_shape(&m).is_none(),"Boolean inverse shortcut not covered");if m.len()==1&&m[0].0!=0{assert!(!self.inv.contains(&m[0].0),"inverse involution shortcut not covered");}let atom=self.atom(1,0,vec![key(&m)]);scale(&atom,c.inverse().unwrap())}
fn bit(&mut self,a:&Lc,index:usize)->Lc{self.requests[2]+=1;assert!(index<254,"high-bit shortcut not covered");if let Some(c)=constant(a){let w=c.to_canonical();return if w[index/64]>>(index%64)&1!=0{vec![(0,Fr::ONE)]}else{vec![]};}let(_,m)=monic(a);assert!(self.bool_shape(&m).is_none(),"Boolean input-bit shortcut not covered");self.atom(2,index,vec![key(a)])}
fn assign(&mut self,side:usize,a:&[Lc;3],inverse:Fr)->Lc{let f=if side==2{let product=if let Some(c)=constant(&a[0]){scale(&a[1],c)}else if let Some(c)=constant(&a[1]){scale(&a[0],c)}else{self.product(&a[0],&a[1])};sub(product,&a[2])}else if let Some(c)=constant(&a[1-side]){if c==Fr::ZERO{vec![]}else{sub(scale(&a[2],c.inverse().unwrap()),&a[side])}}else if constant(&a[2])==Some(Fr::ZERO)&&constant(&a[side])==Some(Fr::ZERO){vec![]}else{self.requests[3]+=1;let(c,other)=monic(&a[1-side]);let output=scale(&a[2],c.inverse().unwrap());self.atom(3,0,vec![key(&other),key(&output),key(&a[side])])};scale(&f,inverse)}
}
fn query(q:&[usize],v:&[Option<Lc>])->Value{let mut full=BTreeSet::new();let mut classes=BTreeMap::<Key,usize>::new();let(mut z,mut c,mut terms)=(0,0,0);for&w in q{let a=v[w].as_ref().unwrap();terms+=a.iter().filter(|v|v.0!=0).count();if constant(a)==Some(Fr::ZERO){z+=1;continue;}c+=usize::from(constant(a).is_some());full.insert(key(a));let(_,m)=monic(a);*classes.entry(key(&m)).or_default()+=1;}json!({"points":q.len(),"zero_rows":z,"nonzero_constant_rows":c,"exact_nonzero_classes":full.len(),"proportional_nonzero_classes":classes.len(),"potential_terms_removed_exact_or_zero":q.len()-full.len(),"potential_terms_removed_proportional_or_zero":q.len()-classes.len(),"merged_proportional_classes":classes.values().filter(|&&n|n>1).count(),"maximum_class_size":classes.values().copied().max().unwrap_or(0),"affine_atom_terms":terms})}
fn verify(data:&[u8])->(Value,Value){
let mut r=Cursor{b:data,at:0};assert_eq!(r.word(),0x3150535a);assert_eq!(r.word(),2);let[nw,ni,np,nc,na,nb,ncoef,nt,ns,nslots,nops]=std::array::from_fn(|_|r.word());assert!(0<np&&np<=ni&&ni<=nw&&nslots<=ns);let queries:[Vec<usize>;2]=[na,nb].map(|n|{let a=(0..n).map(|_|r.word()).collect::<Vec<_>>();assert!(a.iter().all(|&w|w<nw)&&a.windows(2).all(|w|w[0]<w[1]));a});let coeff=(0..ncoef).map(|_|r.field()).collect::<Vec<_>>();assert_eq!(&coeff[..5],&[Fr::ZERO,Fr::ONE,Fr::from(2u64),-Fr::ONE,-Fr::from(2u64)]);let terms=(0..nt).map(|_|{let(c,w)=(r.word(),r.word());assert!(c<ncoef&&w<nw);(c,w)}).collect::<Vec<_>>();let sums=(0..ns).map(|_|{let(p,c,w)=(r.word(),r.word(),r.word());assert!(c<ncoef&&w<nw);(p,c,w)}).collect::<Vec<_>>();let mut values=vec![None;nw+nslots];let mut cse=Cse::new(nw);for w in 0..ni{let a=vec![(w,Fr::ONE)];cse.note(&a);values[w]=Some(a);}
let term=|c:usize,w:usize,v:&Vec<Option<Lc>>|scale(v[w].as_ref().unwrap(),coeff[c]);let(mut nassign,mut nhints,mut nconstraints,mut stored,mut constantsides,mut slotconstants)=(0,0,0,0,0,0);let mut sides=[0;3];let mut rows=vec![false;nc];let mut seen_sums=vec![false;ns];let mut maxterms=1;let mut raw_inv=BTreeMap::<Key,(usize,usize,Fr,Lc)>::new();let mut raw_aliases=vec![];let mut raw_exact=0;let mut raw_inv_count=0;
for op in 0..nops{match r.word(){
1=>{let[kind,a,b,start,end]=std::array::from_fn(|_|r.word());assert!(kind<=1&&a<=b&&b<=nt&&start<end&&end<=nw&&end-start<=256);assert!(kind!=0||end-start==1);let lc=terms[a..b].iter().fold(vec![],|v,&(c,w)|add(v,term(c,w,&values)));
if kind==0{raw_inv_count+=1;let input=norm(terms[a..b].iter().map(|&(c,w)|(w,coeff[c])).collect());let(factor,normal)=monic(&input);assert_ne!(factor,Fr::ZERO);let k=key(&normal);if let Some((source_op,source_wire,source_factor,source_input))=raw_inv.get(&k){assert!(*source_op<op);let output_scale=*source_factor*factor.inverse().unwrap();assert_eq!(scale(&input,output_scale),*source_input);raw_exact+=usize::from(output_scale==Fr::ONE);raw_aliases.push(json!({"op":op,"output_wire":start,"source_op":source_op,"source_wire":source_wire,"output_scale_canonical":output_scale.to_canonical(),"raw_input_crossmultiplication_verified":true}));}else{raw_inv.insert(k,(op,start,factor,input));}}
for(i,w)in(start..end).enumerate(){let out=if kind==0{cse.inverse(&lc)}else{cse.bit(&lc,i)};assert!(values[w].is_none());maxterms=maxterms.max(out.iter().filter(|v|v.0!=0).count());cse.note(&out);values[w]=Some(out);}nhints+=1;},
0=>{let[row,a,b,first]=std::array::from_fn(|_|r.word());assert!(row<nc&&!rows[row]&&a<=b&&b<=ns);rows[row]=true;let mut slot=nw+first;let mut chain=vec![];for j in a..b{assert!(!seen_sums[j]);seen_sums[j]=true;let(p,c,w)=sums[j];let t=term(c,w,&values);chain=match p&0x7fffffff{0x7fffffff=>t,0x7ffffffe=>add(chain,t),w=>add(values[w].clone().unwrap(),t)};if p&0x80000000!=0{assert!(slot<values.len()&&values[slot].is_none());slotconstants+=usize::from(constant(&chain).is_some());maxterms=maxterms.max(chain.iter().filter(|v|v.0!=0).count());values[slot]=Some(chain.clone());slot+=1;stored+=1;}}
let expr:[Lc;3]=std::array::from_fn(|_|{let[tag,a,b]=std::array::from_fn(|_|r.word());match tag{0=>vec![],1=>values[a].clone().unwrap(),2=>norm(vec![(0,coeff[a])]),3=>{let(c,w)=terms[a];term(c,w,&values)},4=>terms[a..b].iter().fold(vec![],|v,&(c,w)|add(v,term(c,w,&values))),_=>panic!("expression tag")}});constantsides+=expr.iter().filter(|a|constant(a).is_some()).count();match r.word(){0=>{},1=>{let[side,w,c]=std::array::from_fn(|_|r.word());assert!(side<=2&&w<nw&&c<ncoef&&coeff[c]!=Fr::ZERO);let inv=r.field();assert_eq!(coeff[c]*inv,Fr::ONE);let out=cse.assign(side,&expr,inv);assert!(values[w].is_none());maxterms=maxterms.max(out.iter().filter(|v|v.0!=0).count());cse.note(&out);values[w]=Some(out);nassign+=1;sides[side]+=1;},_=>panic!("assignment tag")};nconstraints+=1;},_=>panic!("operation tag")}}
assert_eq!(r.at,data.len());assert!(values.iter().all(Option::is_some)&&rows.iter().all(|v|*v)&&seen_sums.iter().all(|v|*v));let q=queries.iter().zip(["A","B"]).map(|(q,n)|(n,query(q,&values))).collect::<BTreeMap<_,_>>();let semantic=json!({"semantic_nodes":ni-1+cse.seen.len(),"interned_nonlinear_nodes":cse.seen.len(),"Boolean_atoms":cse.bits.len(),"product_requests":cse.requests[0],"reused_products":cse.hits[0],"inverse_hint_requests":cse.requests[1],"reused_inverse_hints":cse.hits[1],"bit_hint_output_requests":cse.requests[2],"reused_bit_outputs":cse.hits[2],"guarded_division_requests":cse.requests[3],"reused_guarded_divisions":cse.hits[3],"Boolean_square_rules":0,"Boolean_complement_zero_rules":0,"Boolean_inverse_rules":0,"Boolean_bit_rules":0,"inverse_involution_rules":0,"constant_high_bit_rules":0,"wire_exact_alias_writes":cse.wire_hits[0],"wire_proportional_alias_writes":cse.wire_hits[1]});let summary=json!({"complete":true,"wires":nw,"inputs":ni,"public":np,"constraints":nconstraints,"hints":nhints,"ops":nops,"assignments":nassign,"assignment_sides":sides,"sum_records":ns,"stored_slots":stored,"constant_stored_slots":slotconstants,"constant_expression_sides":constantsides,"maximum_form_terms":maxterms,"analysis_form_terms":values.iter().map(|v|v.as_ref().unwrap().iter().filter(|v|v.0!=0).count()).sum::<usize>(),"semantic_query_classes":q,"semantic_engine":semantic,"raw_inverse_hint_coverage":{"hint_requests":raw_inv_count,"unique_monic_raw_inputs":raw_inv.len(),"certified_aliases":raw_aliases.len(),"exact_copy_aliases":raw_exact,"scaled_aliases":raw_aliases.len()-raw_exact,"full_DAG_not_used_for_raw_signatures":true}});(summary,json!(raw_aliases))}
fn main(){let inputs=read(Path::new(R).join("inputs.json"));let mut cases=BTreeMap::new();let mut private=BTreeMap::new();for shape in["1x2","2x2"]{let file=inputs[shape]["file"].as_str().unwrap();let(v,aliases)=verify(&fs::read(file).unwrap());let original=read(Path::new(R).join(format!("{shape}.json")));for k in["wires","inputs","public","constraints","hints","ops","assignments","assignment_sides","sum_records","stored_slots","constant_stored_slots","constant_expression_sides","maximum_form_terms","analysis_form_terms","semantic_query_classes","semantic_engine"]{assert_eq!(v[k],original[k],"{shape}/{k}");}assert!(v["raw_inverse_hint_coverage"]["certified_aliases"].as_u64().unwrap()<=original["semantic_engine"]["reused_inverse_hints"].as_u64().unwrap());cases.insert(shape,v);private.insert(shape,aliases);}fs::create_dir_all(Path::new(R).join("private")).unwrap();fs::write(Path::new(R).join("private/raw-hint-aliases.json"),serde_json::to_vec_pretty(&json!(private)).unwrap()).unwrap();fs::write(Path::new(R).join("review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"separate_vector_reader_no_model_import":true,"Boolean_and_involution_preconditions_certified_absent":true,"cases":cases,"new_solves":0,"new_proofs":0,"proof_ledger":28847})).unwrap()).unwrap();println!("ReviewPASS:all parsed rows/sums/wires/semantic counters/query classes agree;rawhintcrossmultiplication certificates private;zero newproofs");}
